const OD_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OD_box=(x,y,w,h,o={})=>`<rect x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" width="${(+w).toFixed(1)}" height="${(+h).toFixed(1)}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const OD_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OD_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OD_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* sub- and superscripts that survive line wrapping (tab-separated attributes, raised -0.2em at 72 %) */
const SB=t=>`<tspan\tbaseline-shift="-0.2em"\tfont-size="72%">${t}</tspan>`;
const SP=t=>`<tspan\tbaseline-shift="super"\tfont-size="70%">${t}</tspan>`;
const OD_GREY='#5C6577', OD_PH='#F59F00', OD_PHS='#FFF3BF', OD_EL='#3B5BDB', OD_HO='#E8590C';
/* a photon drawn as a short wave packet: wavelength lam px, from x0 to x1 at height y */
const OD_wave=(x0,x1,y,lam,amp,col,w=4)=>{const p=[];for(let x=x0;x<=x1+0.01;x+=2){const env=Math.sin(Math.PI*(x-x0)/(x1-x0));p.push([x,y-amp*env*Math.sin(2*Math.PI*(x-x0)/lam)])}return OD_poly(p,col,w)};
const OD_dot=(x,y,r,fill,st,lab)=>`<circle cx="${(+x).toFixed(1)}" cy="${(+y).toFixed(1)}" r="${r}" fill="${fill}" stroke="${st}" stroke-width="2"/>`+(lab?OD_T(x,y+r*0.38,lab,{fs:Math.round(r*1.05),fw:800,a:'middle',fill:'#FFFFFF'}):'');
