const OD_ftr=w=>0.44*6.5e4/(w*1e-6)/1e9;                       // GHz, w in µm
const OD_fRC=w=>1/(2*Math.PI*50*13.9*8.85e-12*1e-8/(w*1e-6))/1e9;
const OD_f3=w=>1/Math.sqrt(1/OD_ftr(w)**2+1/OD_fRC(w)**2);
/* a small R against wavelength plot (640 x 330 card): x from 1.0 to 1.8 µm, R from 0 to 1.2 A/W */
