/* three bandwidth bars (GHz) on a baseline y0 */
const OD_bars=(vals,cols,labs,x0,y0,k,bw,gap,fs=22)=>vals.map((v,i)=>{const x=x0+i*(bw+gap);return `<rect x="${x}" y="${(y0-k*v).toFixed(1)}" width="${bw}" height="${(k*v).toFixed(1)}" rx="6" fill="${cols[i]}" fill-opacity=".22" stroke="${cols[i]}" stroke-width="3"/>`+OD_T(x+bw/2,y0-k*v-12,v.toFixed(2),{fs:fs+2,fw:800,a:'middle',fill:cols[i]})+OD_T(x+bw/2,y0+30,labs[i],{fs,fw:700,a:'middle',fill:OD_GREY})}).join('');

