 +`<rect x="${wx(0.8)}" y="404" width="${(wx(1.11)-wx(0.8)).toFixed(1)}" height="26" rx="6" fill="${OD_EL}" fill-opacity=".25" stroke="${OD_EL}" stroke-width="2"/>`+OD_T(wx(0.8)+10,424,'Si to 1.11',{fs:20,fw:800,fill:OD_EL})
